#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int minDifference(std::vector<int>& nums) {
        int n = nums.size();
        int min_diff = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (nums[i] != -1 && nums[i + 1] != -1) {
                min_diff = std::max(min_diff, std::abs(nums[i] - nums[i + 1]));
            }
        }

        std::vector<int> adj;
        for (int i = 0; i < n; ++i) {
            if (nums[i] == -1) continue;
            if ((i > 0 && nums[i - 1] == -1) || (i < n - 1 && nums[i + 1] == -1)) {
                adj.push_back(nums[i]);
            }
        }

        if (adj.empty()) return min_diff;

        int min_v = *std::min_element(adj.begin(), adj.end());
        int max_v = *std::max_element(adj.begin(), adj.end());

        auto check = [&](int d) {
            if (d < min_diff) return false;
            int x = min_v + d;
            int y = max_v - d;
            if (x > y) x = y = (min_v + max_v) / 2;

            int i = 0;
            while (i < n) {
                if (nums[i] == -1) {
                    int start = i;
                    while (i < n && nums[i] == -1) ++i;
                    int end = i;
                    int left_val = (start > 0) ? nums[start - 1] : -1;
                    int right_val = (end < n) ? nums[end] : -1;

                    bool can_x = (left_val == -1 || std::abs(left_val - x) <= d) && (right_val == -1 || std::abs(right_val - x) <= d);
                    bool can_y = (left_val == -1 || std::abs(left_val - y) <= d) && (right_val == -1 || std::abs(right_val - y) <= d);
                    bool can_xy = (end - start >= 2) && (std::abs(x - y) <= d) && (
                        ((left_val == -1 || std::abs(left_val - x) <= d) && (right_val == -1 || std::abs(right_val - y) <= d)) ||
                        ((left_val == -1 || std::abs(left_val - y) <= d) && (right_val == -1 || std::abs(right_val - x) <= d))
                    );
                    if (!can_x && !can_y && !can_xy) return false;
                } else {
                    ++i;
                }
            }
            return true;
        };

        int low = min_diff, high = max_v - min_v, ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minDifference(int[] nums) {
        int n = nums.length;
        int minDiff = 0;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] != -1 && nums[i + 1] != -1) {
                minDiff = Math.max(minDiff, Math.abs(nums[i] - nums[i + 1]));
            }
        }

        List<Integer> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums[i] == -1) continue;
            if ((i > 0 && nums[i - 1] == -1) || (i < n - 1 && nums[i + 1] == -1)) {
                adj.add(nums[i]);
            }
        }

        if (adj.isEmpty()) return minDiff;

        int minV = Collections.min(adj);
        int maxV = Collections.max(adj);

        int low = minDiff, high = maxV - minV, ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid, nums, n, minDiff, minV, maxV)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean check(int d, int[] nums, int n, int minDiff, int minV, int maxV) {
        if (d < minDiff) return false;
        int x = minV + d;
        int y = maxV - d;
        if (x > y) x = y = (minV + maxV) / 2;

        int i = 0;
        while (i < n) {
            if (nums[i] == -1) {
                int start = i;
                while (i < n && nums[i] == -1) i++;
                int end = i;
                int leftVal = (start > 0) ? nums[start - 1] : -1;
                int rightVal = (end < n) ? nums[end] : -1;

                boolean canX = (leftVal == -1 || Math.abs(leftVal - x) <= d) && (rightVal == -1 || Math.abs(rightVal - x) <= d);
                boolean canY = (leftVal == -1 || Math.abs(leftVal - y) <= d) && (rightVal == -1 || Math.abs(rightVal - y) <= d);
                boolean canXY = (end - start >= 2) && (Math.abs(x - y) <= d) && (
                    ((leftVal == -1 || Math.abs(leftVal - x) <= d) && (rightVal == -1 || Math.abs(rightVal - y) <= d)) ||
                    ((leftVal == -1 || Math.abs(leftVal - y) <= d) && (rightVal == -1 || Math.abs(rightVal - x) <= d))
                );
                if (!canX && !canY && !canXY) return false;
            } else {
                i++;
            }
        }
        return true;
    }
}

var minDifference = function(nums) {
    const n = nums.length;
    let minDiff = 0;
    for (let i = 0; i < n - 1; i++) {
        if (nums[i] !== -1 && nums[i + 1] !== -1) {
            minDiff = Math.max(minDiff, Math.abs(nums[i] - nums[i + 1]));
        }
    }

