        if (nums[i] === -1) continue;
        if ((i > 0 && nums[i - 1] === -1) || (i < n - 1 && nums[i + 1] === -1)) {
            adj.push(nums[i]);
        }
    }

    if (adj.length === 0) return minDiff;

    let minV = Math.min(...adj);
    let maxV = Math.max(...adj);

    function check(d) {
        if (d < minDiff) return false;
        let x = minV + d;
        let y = maxV - d;
        if (x > y) x = y = Math.floor((minV + maxV) / 2);

        let i = 0;
        while (i < n) {
            if (nums[i] === -1) {
                const start = i;
                while (i < n && nums[i] === -1) i++;
                const end = i;
                const leftVal = (start > 0) ? nums[start - 1] : null;
                const rightVal = (end < n) ? nums[end] : null;

                const canX = (leftVal === null || Math.abs(leftVal - x) <= d) && (rightVal === null || Math.abs(rightVal - x) <= d);
                const canY = (leftVal === null || Math.abs(leftVal - y) <= d) && (rightVal === null || Math.abs(rightVal - y) <= d);
                const canXY = (end - start >= 2) && (Math.abs(x - y) <= d) && (
                    ((leftVal === null || Math.abs(leftVal - x) <= d) && (rightVal === null || Math.abs(rightVal - y) <= d)) ||
                    ((leftVal === null || Math.abs(leftVal - y) <= d) && (rightVal === null || Math.abs(rightVal - x) <= d))
                );
                if (!canX && !canY && !canXY) return false;
            } else {
                i++;
            }
        }
        return true;
    }

    let low = minDiff, high = maxV - minV, ans = high;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
